from base_sensor import BaseVirtualSensor

class ADS1115_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs[0x00] = 0x0000  # CONVERSION
        self.regs[0x01] = 0x8583  # CONFIG
        self.regs[0x02] = 0x8000  # LO_THRESH
        self.regs[0x03] = 0x7FFF  # HI_THRESH

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:02X}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:02X}")

        if addr == 0x00:  # CONVERSION is read-only
            return

        if nbytes == 1:
            mask = 0xFF << 8
            self.regs[addr] = (self.regs[addr] & ~mask) | (data << 8)
        else:
            self.regs[addr] = data

