        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:02X}")

        if nbytes == 1:
            mask = 0xFF << 8
            data = (data << 8) & mask
            value = self.regs[addr] & ~mask
            self.regs[addr] = value | data
        else:
            self.regs[addr] = data & 0xFFFF

        # CONFIG register is read-only except for OS bit
        if addr == 0x01:
            os_bit = self.regs[addr] & (1 << 15)
            self.regs[addr] = 0x8583 | os_bit
